#!/usr/bin/env bash
# Builds the iOS app: libethornell_mobile.a for device and simulator, packed as
# Vendor/Ethornell.xcframework, then the Xcode project generated by XcodeGen.
#
#   platform/ios/build.sh            # simulator app (build/sim/Ethornell.app)
#   platform/ios/build.sh device     # unsigned device app + build/Ethornell-unsigned.ipa
#
# The device build is unsigned: re-sign the .ipa (AltStore, SideStore, or
# your own certificate), or open Ethornell.xcodeproj and pick a team.
# Needs: Xcode, rustup, xcodegen (brew install xcodegen).
set -euo pipefail

MODE="${1:-sim}"
IOS_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$IOS_DIR/../.." && pwd)"
export IPHONEOS_DEPLOYMENT_TARGET="${IPHONEOS_DEPLOYMENT_TARGET:-15.0}"

command -v xcodegen >/dev/null || { echo "xcodegen not found (brew install xcodegen)" >&2; exit 1; }
rustup target add aarch64-apple-ios aarch64-apple-ios-sim >/dev/null

cd "$ROOT"
for target in aarch64-apple-ios aarch64-apple-ios-sim; do
  cargo build -p ethornell-mobile --release --locked --target "$target"
done

VENDOR="$IOS_DIR/Vendor"
rm -rf "$VENDOR/Ethornell.xcframework"
mkdir -p "$VENDOR"
xcodebuild -create-xcframework \
  -library "$ROOT/target/aarch64-apple-ios/release/libethornell_mobile.a" -headers "$IOS_DIR/include" \
  -library "$ROOT/target/aarch64-apple-ios-sim/release/libethornell_mobile.a" -headers "$IOS_DIR/include" \
  -output "$VENDOR/Ethornell.xcframework"

cd "$IOS_DIR"
xcodegen generate --quiet

case "$MODE" in
  sim)
    xcodebuild -project Ethornell.xcodeproj -scheme Ethornell -configuration Release \
      -sdk iphonesimulator -destination 'generic/platform=iOS Simulator' \
      -derivedDataPath build/derived ARCHS=arm64 ONLY_ACTIVE_ARCH=NO \
      CODE_SIGNING_ALLOWED=NO build
    rm -rf build/sim && mkdir -p build/sim
    cp -R build/derived/Build/Products/Release-iphonesimulator/Ethornell.app build/sim/
    echo "build/sim/Ethornell.app"
    ;;
  device)
    xcodebuild -project Ethornell.xcodeproj -scheme Ethornell -configuration Release \
      -sdk iphoneos -destination 'generic/platform=iOS' \
      -derivedDataPath build/derived \
      CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY= build
    rm -rf build/ipa && mkdir -p build/ipa/Payload
    cp -R build/derived/Build/Products/Release-iphoneos/Ethornell.app build/ipa/Payload/
    (cd build/ipa && zip -qry ../Ethornell-unsigned.ipa Payload)
    echo "build/Ethornell-unsigned.ipa"
    ;;
  *)
    echo "usage: $0 [sim|device]" >&2
    exit 1
    ;;
esac
